import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.net.InetAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.net.SocketTimeoutException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

public class EchoClientTest {
    static int failures = 0;
    static final List<String> received = new ArrayList<>();
    static String serverProblem = null;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String call(int port, String message) {
        try {
            return EchoClient.askServer(port, message);
        } catch (Throwable t) {
            return "askServer threw " + t.getClass().getSimpleName();
        }
    }

    /** Serves exactly howMany one-line conversations, then finishes. */
    static Thread startEchoServer(ServerSocket server, int howMany) {
        Thread thread = new Thread(() -> {
            try {
                for (int i = 0; i < howMany; i++) {
                    Socket client = server.accept();
                    try {
                        BufferedReader in = new BufferedReader(
                                new InputStreamReader(client.getInputStream(), StandardCharsets.UTF_8));
                        BufferedWriter out = new BufferedWriter(
                                new OutputStreamWriter(client.getOutputStream(), StandardCharsets.UTF_8));
                        String line = in.readLine();
                        if (line == null) {
                            line = "";
                        }
                        received.add(line);
                        out.write("echo: " + line);
                        out.write("\n");
                        out.flush();
                    } finally {
                        client.close();
                    }
                }
            } catch (SocketTimeoutException timeout) {
                // No client showed up -- askServer probably never connected.
            } catch (Exception e) {
                serverProblem = e.getClass().getSimpleName();
            }
        });
        thread.setDaemon(true);
        thread.start();
        return thread;
    }

    public static void main(String[] args) throws Exception {
        ServerSocket server = null;
        Thread serverThread = null;
        String first = "not run";
        String second = "not run";
        String third = "not run";
        try {
            server = new ServerSocket(0, 8, InetAddress.getByName("127.0.0.1"));
            server.setSoTimeout(700);
            int port = server.getLocalPort();
            serverThread = startEchoServer(server, 3);
            first = call(port, "hello");
            second = call(port, "Java Sockets");
            third = call(port, "");
        } finally {
            if (serverThread != null) {
                serverThread.join(3000);
            }
            if (server != null) {
                try {
                    server.close();
                } catch (IOException ignored) {
                    // nothing useful to do
                }
            }
        }

        check("askServer(port, \"hello\")", "echo: hello", first);
        check("askServer(port, \"Java Sockets\")", "echo: Java Sockets", second);
        check("askServer(port, \"\") still gets a reply", "echo: ", third);
        check("server accepted three connections", 3, received.size());
        check("server saw exactly what the client sent", "[hello, Java Sockets, ]", received.toString());
        check("server hit no protocol errors", null, serverProblem);
        check("reply comes back without its newline", Boolean.TRUE,
                Boolean.valueOf(first != null && !first.endsWith("\n")));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

